src/cli.js
import { addNote, loadNotes, removeNote } from "./store.js";

const dataDir = process.env.TINY_NOTES_DIR ?? ".data";
const [command, ...args] = process.argv.slice(2);

if (command === "add") {
  const text = args.join(" ").trim();
  if (!text) {
    console.error("usage: tiny-notes add <text>");
    process.exitCode = 2;
  } else {
    const note = await addNote(dataDir, text);
    console.log(note.id);
  }
} else if (command === "list") {
  for (const note of await loadNotes(dataDir)) {
    console.log(`${note.id}\t${note.text}`);
  }
} else if (command === "remove") {
  if (!args[0]) {
    console.error("usage: tiny-notes remove <id>");
    process.exitCode = 2;
  } else {
    const removed = await removeNote(dataDir, args[0]);
    if (!removed) {
      console.error(`note not found: ${args[0]}`);
      process.exitCode = 1;
    }
  }
} else {
  console.error("usage: tiny-notes <add|list|remove> ...");
  process.exitCode = 2;
}
