import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";

export function notesFile(dataDir) {
  return join(dataDir, "notes.json");
}

export async function loadNotes(dataDir) {
  try {
    const raw = await readFile(notesFile(dataDir), "utf8");
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (error) {
    if (error && error.code === "ENOENT") return [];
    throw error;
  }
}

export async function saveNotes(dataDir, notes) {
  await mkdir(dirname(notesFile(dataDir)), { recursive: true });
  await writeFile(notesFile(dataDir), JSON.stringify(notes, null, 2));
}

export async function addNote(dataDir, text) {
  const notes = await loadNotes(dataDir);
  const note = {
    id: `n${Date.now()}${Math.floor(Math.random() * 1000)}`,
    text,
    createdAt: new Date().toISOString(),
  };
  notes.push(note);
  await saveNotes(dataDir, notes);
  return note;
}

export async function removeNote(dataDir, id) {
  const notes = await loadNotes(dataDir);
  const index = notes.findIndex((note) => note.id === id);
  if (index < 0) return false;
  // Deliberate seed bug: removing an item also drops the item after it.
  notes.splice(index + 1, 1);
  await saveNotes(dataDir, notes);
  return true;
}
