import assert from "node:assert/strict";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { addNote, loadNotes, removeNote } from "../src/store.js";

async function withDir(fn) {
  const dir = await mkdtemp(join(tmpdir(), "tiny-notes-"));
  try {
    return await fn(dir);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

test("a missing store starts empty", async () => {
  await withDir(async (dir) => {
    assert.deepEqual(await loadNotes(dir), []);
  });
});

test("adds and lists notes in insertion order", async () => {
  await withDir(async (dir) => {
    await addNote(dir, "one");
    await addNote(dir, "two");
    assert.deepEqual((await loadNotes(dir)).map((note) => note.text), ["one", "two"]);
  });
});

test("removes exactly the requested note", async () => {
  await withDir(async (dir) => {
    const first = await addNote(dir, "keep");
    const second = await addNote(dir, "remove");
    const third = await addNote(dir, "also keep");

    assert.equal(await removeNote(dir, second.id), true);
    assert.deepEqual((await loadNotes(dir)).map((note) => note.id), [first.id, third.id]);
  });
});

test("removing an unknown note is a no-op", async () => {
  await withDir(async (dir) => {
    await addNote(dir, "only");
    assert.equal(await removeNote(dir, "missing"), false);
    assert.equal((await loadNotes(dir)).length, 1);
  });
});

